package de.example.reports.gui;
import io.papermc.paper.event.packet.UncheckedSignChangeEvent; import net.kyori.adventure.text.Component; import org.bukkit.Location; import org.bukkit.Material; import org.bukkit.block.TileState; import org.bukkit.block.data.BlockData; import org.bukkit.block.sign.Side; import org.bukkit.entity.Player; import org.bukkit.event.EventHandler; import org.bukkit.event.Listener; import org.bukkit.plugin.java.JavaPlugin; import java.util.*; import java.util.function.Consumer;
/** Native Paper virtual-sign prompt; pending state is bound to the player UUID and expires on response/quit. */
public final class SignInput implements Listener { private final Map<UUID,Consumer<List<Component>>> pending=new HashMap<>(); public SignInput(JavaPlugin plugin){plugin.getServer().getPluginManager().registerEvents(this,plugin);} public void open(Player player, Consumer<List<Component>> callback){open(player,"",callback);} public void open(Player player,String title, Consumer<List<Component>> callback){pending.put(player.getUniqueId(),callback); Location at=player.getLocation().getBlock().getLocation(); BlockData data=Material.OAK_SIGN.createBlockData(); TileState state=(TileState)data.createBlockState(); player.sendBlockChange(at,data); player.sendBlockUpdate(at,state); player.openVirtualSign(at,Side.FRONT);}
 @EventHandler public void input(UncheckedSignChangeEvent event){Consumer<List<Component>> c=pending.remove(event.getPlayer().getUniqueId());if(c==null)return;event.setCancelled(true);c.accept(event.lines());}
 public void clear(UUID id){pending.remove(id);} }
